<?php
require_once 'functions.php';require_login();$id=uid();
$s=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN type='income' THEN amount ELSE 0 END),0) income,COALESCE(SUM(CASE WHEN type='expense' THEN amount ELSE 0 END),0) expenses FROM transactions WHERE user_id=?");$s->execute([$id]);$tot=$s->fetch();$balance=(float)$tot['income']-(float)$tot['expenses'];
$s=$pdo->prepare('SELECT * FROM transactions WHERE user_id=? ORDER BY transaction_date DESC,id DESC LIMIT 6');$s->execute([$id]);$recent=$s->fetchAll();$month=date('Y-m');$s=$pdo->prepare('SELECT amount FROM budgets WHERE user_id=? AND month_key=?');$s->execute([$id,$month]);$budget=(float)($s->fetch()['amount']??0);$s=$pdo->prepare("SELECT COALESCE(SUM(amount),0) spent FROM transactions WHERE user_id=? AND type='expense' AND DATE_FORMAT(transaction_date,'%Y-%m')=?");$s->execute([$id,$month]);$spent=(float)$s->fetch()['spent'];
start_page('Dashboard','dashboard.php');?>
<section class="hero"><div class="hero-copy"><span class="tag">YOUR FINANCES AT A GLANCE</span><h1>Make room for<br><em>what matters.</em></h1><p>Every small money decision adds up. Here’s your latest snapshot.</p><a class="hero-button" href="transactions.php">＋ Add transaction　→</a></div><div class="hero-art"><div class="orb orb-a"></div><div class="orb orb-b"></div><div class="balance-card"><span class="bubble">↗</span><small>Net balance</small><strong><?=money($balance)?></strong><small class="green">Your money overview</small></div><span class="coin">₹</span><span class="spark">✦</span></div></section>
<div class="section-title"><div><h2>Your overview</h2><p>Here’s how things are looking.</p></div><span class="date-chip">◷ <?=date('d M Y')?></span></div>
<section class="metrics"><article class="metric purple"><div>Total balance <span>◈</span></div><strong><?=money($balance)?></strong><small>Income minus expenses</small></article><article class="metric mint"><div>Total income <span>↗</span></div><strong><?=money($tot['income'])?></strong><small>Money received</small></article><article class="metric peach"><div>Total expenses <span>↘</span></div><strong><?=money($tot['expenses'])?></strong><small>Money spent</small></article></section>
<section class="two-col"><article class="panel"><div class="panel-head"><div><h2>Recent transactions</h2><p>Your latest money activity</p></div><a class="text-link" href="transactions.php">View all →</a></div><?php if(!$recent):?><div class="empty"><b>Your story starts here</b><p>Add your first income or expense to see activity.</p><a class="text-link" href="transactions.php">Add a transaction →</a></div><?php else:?><div class="tx-list"><?php foreach($recent as $t):?><div class="tx-row"><span class="tx-icon <?=$t['type']?>"><?=$t['type']==='income'?'↗':'↘'?></span><div class="tx-desc"><b><?=e($t['description']?:$t['category'])?></b><small><?=e($t['category'])?> · <?=date('d M',strtotime($t['transaction_date']))?></small></div><strong class="<?=$t['type']==='income'?'green':'red'?>"><?=$t['type']==='income'?'+':'−'?><?=money($t['amount'])?></strong></div><?php endforeach;?></div><?php endif;?></article><article class="panel"><div class="panel-head"><div><h2>Monthly budget</h2><p><?=date('F Y')?></p></div><span class="round-icon">◷</span></div><div class="budget-amount"><?=money($spent)?> <small>spent</small></div><div class="progress"><span style="width:<?=$budget>0?min(100,$spent/$budget*100):0?>%"></span></div><div class="budget-foot"><span><?=money(max(0,$budget-$spent))?> remaining</span><span><?=$budget>0?round($spent/$budget*100).'%':'No budget'?></span></div><?php if(!$budget):?><div class="note">Set a budget to keep your spending in view.</div><?php elseif($spent>=$budget):?><div class="alert danger">You’ve reached your monthly budget.</div><?php elseif($spent>=$budget*.8):?><div class="alert warning">You’ve used 80% of your budget.</div><?php else:?><div class="note">You’re within your monthly limit. Keep it up!</div><?php endif;?><a class="soft-button" href="budget.php">Manage budget →</a></article></section>
<?php end_page();?>
